Repair the complete CommonJS source below. It must export exactly `{ centralReading }`. `centralReading(values)` requires a non-empty array containing only finite numbers; empty or malformed input throws `TypeError`. It returns the middle value after ascending numeric ordering. For an even number of readings, return the arithmetic mean of the two central values. Preserve duplicates and negative values. The input array must not be mutated, retained, or returned.

Known-bad source:

'use strict';

function centralReading(values) {
  if (!Array.isArray(values) || values.length === 0 ||
      !values.every(value => typeof value === 'number' && Number.isFinite(value))) {
    throw new TypeError('Expected a non-empty array of finite numbers');
  }
  const ordered = values.slice().sort((a, b) => a - b);
  const middle = Math.floor(ordered.length / 2);
  if (ordered.length % 2 === 1) return ordered[middle];
  return (ordered[middle] + ordered[middle + 1]) / 2;
}

module.exports = { centralReading };

