'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api), ['centralReading']);
const { centralReading } = api;

assert.equal(centralReading([7]), 7);
assert.equal(centralReading([3, 1, 2]), 2);
assert.equal(centralReading([4, 1, 3, 2]), 2.5);
assert.equal(centralReading([100, 1]), 50.5);
assert.equal(centralReading([-10, -2, -5, -2]), -3.5);
assert.equal(centralReading([2, 2, 2, 9, 9]), 2);
assert.equal(centralReading([-0, 0]), 0);

const input = [9, -1, 4, 4, 2, 100];
const snapshot = input.slice();
const value = centralReading(input);
assert.equal(value, 4);
assert.deepEqual(input, snapshot);
assert.equal(typeof value, 'number');

for (const invalid of [null, undefined, {}, '1,2', [], [1, '2'], [NaN], [Infinity], [-Infinity], [1, null], [1, undefined]]) {
  assert.throws(() => centralReading(invalid), TypeError);
}

